// at is the moment every lock test pretends it is, so that golden output can
// be written out in full.
var lockTime = time.Date(2026, 10, 9, 8, 0, 0, 0, time.UTC)

// goldenLock is exactly what flow writes for the state sampleLock builds. It
// is written out in full: a generated file nobody can read is a generated file
// nobody reviews.
const goldenLock = `# generated by flow — do not edit; use flow doctor --fix
version: 1
flow_version: v0.3.0
config_hash: sha256:2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824
resolved:
  forge.default_branch: main
  tracker.project: "3"
  tracker.project_id: PVT_kwHOAAJxyc4BFQpq
  tracker.status_field_id: PVTSSF_lAHOAAJxyc4BFQpqzg3Xq1A
  tracker.status_options.backlog: f75ad846
  tracker.status_options.done: "98236657"
  tracker.status_options.in_progress: 47fc9ee4
  tracker.status_options.in_review: df73e18b
  tracker.status_options.ready: 61e4505c
observed:
  forge.protection:
    hash: sha256:433c3507c372d907a357bb02e4632eebc85431812c03aa44ac31b6a66dc26e91
    at: 2026-10-09T08:00:00Z
  tracker.status_options:
    hash: sha256:a793ab8fcc2afce5e42b3044090719ddaff19741697d93b3b7f36838dd5e825c
    at: 2026-10-09T08:00:00Z
created:
  - kind: tracker.status_option
    id: df73e18b
    name: In review
    at: 2026-10-09T08:00:00Z
followups:
  - check: tracker.native.pr_merged
    ticket: '#12'
    owner: '@17twenty'
    opened_at: 2026-10-09T08:00:00Z
    state: open
attestations:
  - check: tracker.native.issue_closed
    by: '@17twenty'
    note: Item closed → Done enabled
    at: 2026-10-09T08:00:00Z
    expires_at: 2026-11-08T08:00:00Z
`

// sampleLock builds the state goldenLock describes.
func sampleLock() *Lock {
	lock := NewLock("v0.3.0")
	lock.ConfigHash = Hash([]byte("hello"))

	for key, value := range map[string]string{
		"tracker.project":                    "3",
		"tracker.project_id":                 "PVT_kwHOAAJxyc4BFQpq",
		"tracker.status_field_id":            "PVTSSF_lAHOAAJxyc4BFQpqzg3Xq1A",
		"tracker.status_options.backlog":     "f75ad846",
		"tracker.status_options.ready":       "61e4505c",
		"tracker.status_options.in_progress": "47fc9ee4",
		"tracker.status_options.in_review":   "df73e18b",
		"tracker.status_options.done":        "98236657",
		"forge.default_branch":               "main",
	} {
		lock.Resolve(key, value)
	}

	lock.Observe("tracker.status_options", Hash([]byte("options")), lockTime)
	lock.Observe("forge.protection", Hash([]byte("protection")), lockTime)
	lock.Record(Creation{Kind: "tracker.status_option", ID: "df73e18b", Name: "In review", At: lockTime})
	lock.FollowUps = append(lock.FollowUps, FollowUp{
		Check:    "tracker.native.pr_merged",
		Ticket:   "#12",
		Owner:    "@17twenty",
		OpenedAt: lockTime,
		State:    FollowUpOpen,
	})
	lock.Attestations = append(lock.Attestations, Attestation{
		Check:     "tracker.native.issue_closed",
		By:        "@17twenty",
		Note:      "Item closed → Done enabled",
		At:        lockTime,
		ExpiresAt: lockTime.Add(30 * 24 * time.Hour),
	})
	return lock
}

func TestLockBytesAreGolden(t *testing.T) {
	got, err := sampleLock().Bytes()
	if err != nil {
		t.Fatalf("Bytes: %v", err)
	}
	if string(got) != goldenLock {
		t.Errorf("lock rendered as\n%s\nwant\n%s", got, goldenLock)
	}
	if !strings.HasSuffix(string(got), "\n") {
		t.Error("the lock does not end with a newline")
	}
}

// TestLockBytesAreDeterministic builds the same knowledge in a different order
// and insists on the same bytes: a lock that reorders itself turns every run
// into a diff.
func TestLockBytesAreDeterministic(t *testing.T) {
	shuffled := NewLock("v0.3.0")
	shuffled.ConfigHash = Hash([]byte("hello"))
	original := sampleLock()

	for _, key := range []string{
		"tracker.status_options.ready", "forge.default_branch", "tracker.project",
		"tracker.status_options.done", "tracker.project_id", "tracker.status_options.backlog",
		"tracker.status_field_id", "tracker.status_options.in_review", "tracker.status_options.in_progress",
	} {
		shuffled.Resolve(key, original.Resolved[key])
	}
	shuffled.Observe("forge.protection", Hash([]byte("protection")), lockTime)
	shuffled.Observe("tracker.status_options", Hash([]byte("options")), lockTime)
	shuffled.Record(Creation{Kind: "tracker.status_option", ID: "df73e18b", Name: "In review", At: lockTime})
	shuffled.FollowUps = original.FollowUps
	shuffled.Attestations = original.Attestations

	first, err := shuffled.Bytes()
	if err != nil {
		t.Fatalf("Bytes: %v", err)
	}
	if string(first) != goldenLock {
		t.Errorf("a lock built in another order rendered as\n%s", first)
	}

	second, err := shuffled.Bytes()
	if err != nil {
		t.Fatalf("Bytes: %v", err)
	}
	if string(second) != string(first) {
		t.Error("rendering the same lock twice gave different bytes")
	}
}

func TestLockRoundTrips(t *testing.T) {
	want := sampleLock()
	data, err := want.Bytes()
	if err != nil {
		t.Fatalf("Bytes: %v", err)
	}

	got, err := ParseLock(data, "flow.lock")
	if err != nil {
		t.Fatalf("ParseLock: %v", err)
	}
	again, err := got.Bytes()
	if err != nil {
		t.Fatalf("Bytes: %v", err)
	}
	if string(again) != string(data) {
		t.Errorf("reading and rewriting changed the lock:\n%s", again)
	}
	if value, ok := got.Lookup("tracker.project"); !ok || value != "3" {
		t.Errorf("Lookup(tracker.project) = %q, %v", value, ok)
	}
	if _, ok := got.Lookup("tracker.absent"); ok {
		t.Error("Lookup found something that was never resolved")
	}
	if got.Observed["forge.protection"].At.Location() != time.UTC {
		t.Error("timestamps did not come back in UTC")
	}
}

// TestObservationTimestampChurn pins the rule that keeps the lock quiet: a
// timestamp only moves when the observed state changed, or once a day
// (spec 03 §3).
func TestObservationTimestampChurn(t *testing.T) {
	const key = "tracker.status_options"
	tests := []struct {
		name  string
		hash  string
		after time.Duration
		moved bool
	}{
		{"unchanged a minute later", "sha256:aa", time.Minute, false},
		{"unchanged an hour later", "sha256:aa", time.Hour, false},
		{"unchanged just inside the day", "sha256:aa", ObservationTTL - time.Second, false},
		{"unchanged a day later", "sha256:aa", ObservationTTL, true},
		{"unchanged a week later", "sha256:aa", 7 * 24 * time.Hour, true},
		{"changed a minute later", "sha256:bb", time.Minute, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			lock := NewLock("v0")
			lock.Observe(key, "sha256:aa", lockTime)
			later := lockTime.Add(tt.after)
			lock.Observe(key, tt.hash, later)

			got := lock.Observed[key]
			if got.Hash != tt.hash {
				t.Errorf("hash = %q, want %q", got.Hash, tt.hash)
			}
			want := lockTime
			if tt.moved {
				want = later
			}
			if !got.At.Equal(want) {
				t.Errorf("at = %s, want %s", got.At.Format(time.RFC3339), want.Format(time.RFC3339))
			}
		})
	}

	t.Run("a clock that went backwards does not move it", func(t *testing.T) {
		lock := NewLock("v0")
		lock.Observe(key, "sha256:aa", lockTime)
		lock.Observe(key, "sha256:aa", lockTime.Add(-time.Hour))
		if !lock.Observed[key].At.Equal(lockTime) {
			t.Errorf("at = %s, want it left alone", lock.Observed[key].At.Format(time.RFC3339))
		}
	})

	t.Run("timestamps are stored in UTC to the second", func(t *testing.T) {
		zone := time.FixedZone("UTC+2", 2*60*60)
		lock := NewLock("v0")
		lock.Observe(key, "sha256:aa", time.Date(2026, 10, 9, 10, 0, 0, 123456789, zone))
		got := lock.Observed[key].At
		if !got.Equal(lockTime) || got.Nanosecond() != 0 || got.Location() != time.UTC {
			t.Errorf("at = %v, want %v in UTC with no fraction", got, lockTime)
		}
	})
}

func TestRecordReplacesTheSameThing(t *testing.T) {
	lock := NewLock("v0")
	lock.Record(Creation{Kind: "tracker.status_option", ID: "a", Name: "Ready", At: lockTime})
	lock.Record(Creation{Kind: "tracker.status_option", ID: "a", Name: "Ready for review", At: lockTime})
	lock.Record(Creation{Kind: "tracker.status_option", ID: "b", Name: "Done", At: lockTime})
	if len(lock.Created) != 2 {
		t.Fatalf("created %d things, want 2: %v", len(lock.Created), lock.Created)
	}
	if lock.Created[0].Name != "Ready for review" {
		t.Errorf("created[0] = %#v, want the later name", lock.Created[0])
	}
}

// A required status check is only its name. Two of them are two things, and
// the second must not overwrite the record of the first.
func TestRecordKeepsTwoThingsWithNoID(t *testing.T) {
	lock := NewLock("v0")
	lock.Record(Creation{Kind: "forge.required_status", Name: "flow/policy", At: lockTime})
	lock.Record(Creation{Kind: "forge.required_status", Name: "test", At: lockTime})
	lock.Record(Creation{Kind: "forge.required_status", Name: "test", At: lockTime.Add(time.Hour)})
	if len(lock.Created) != 2 {
		t.Fatalf("created %d things, want 2: %v", len(lock.Created), lock.Created)
	}
}

// An earlier flow wrote `forge.required_statu` (issue #204). This one reads
// it as the check it was, so the record still counts and is rewritten right.
func TestLockReadsTheKindAnEarlierFlowMisspelt(t *testing.T) {
	src := "version: 1\nflow_version: v0\ncreated:\n  - kind: forge.required_statu\n    name: flow/policy\n    at: 2026-10-26T22:23:10Z\n"
	lock, err := ParseLock([]byte(src), "")
	if err != nil {
		t.Fatalf("ParseLock: %v", err)
	}
	if got := lock.Created[0].Kind; got != "forge.required_status" {
		t.Errorf("the kind reads as %q, want forge.required_status", got)
	}
	out, err := lock.Bytes()
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(out), "required_statu\n") {
		t.Errorf("the lock is written back misspelt:\n%s", out)
	}
}

func TestWriteLockIsAtomic(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, LockPath)

	if err := WriteLock(path, sampleLock()); err != nil {
		t.Fatalf("WriteLock: %v", err)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if string(data) != goldenLock {
		t.Errorf("wrote\n%s", data)
	}

	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 1 {
		t.Errorf("the directory holds %d files, want only the lock: %v", len(entries), entries)
	}

	// Writing again replaces the file in place, leaving no debris behind.
	second := sampleLock()
	second.FlowVersion = "v0.4.0"
	if err := WriteLock(path, second); err != nil {
		t.Fatalf("WriteLock: %v", err)
	}
	data, err = os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(data), "flow_version: v0.4.0") {
		t.Error("the second write did not replace the file")
	}
	entries, _ = os.ReadDir(dir)
	if len(entries) != 1 {
		t.Errorf("the directory holds %d files after rewriting: %v", len(entries), entries)
	}
}

func TestWriteLockKeepsTheFileMode(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, LockPath)
	if err := os.WriteFile(path, []byte("# old\n"), 0o640); err != nil {
		t.Fatal(err)
	}
	if err := WriteLock(path, sampleLock()); err != nil {
		t.Fatalf("WriteLock: %v", err)
	}
	info, err := os.Stat(path)
	if err != nil {
		t.Fatal(err)
	}
	if info.Mode().Perm() != 0o640 {
		t.Errorf("mode = %v, want the mode the file already had", info.Mode().Perm())
	}
}

func TestWriteLockReportsWhereItFailed(t *testing.T) {
	path := filepath.Join(t.TempDir(), "absent", LockPath)
	err := WriteLock(path, sampleLock())
	if err == nil {
		t.Fatal("WriteLock succeeded into a directory that does not exist")
	}
	var user *core.UserError
	if !errors.As(err, &user) {
		t.Fatalf("error is %T, want a core.UserError", err)
	}
	if !strings.Contains(user.What, path) {
		t.Errorf("What = %q, want it to name the file", user.What)
	}
	if core.ExitCode(err) != core.ExitUsage {
		t.Errorf("ExitCode = %d, want %d", core.ExitCode(err), core.ExitUsage)
	}
}

func TestLoadLock(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, LockPath)
	if err := WriteLock(path, sampleLock()); err != nil {
		t.Fatal(err)
	}
	lock, err := LoadLock(path)
	if err != nil {
		t.Fatalf("LoadLock: %v", err)
	}
	if lock.FlowVersion != "v0.3.0" {
		t.Errorf("flow_version = %q", lock.FlowVersion)
	}

	_, err = LoadLock(filepath.Join(dir, "absent.lock"))
	if !errors.Is(err, core.ErrNotFound) {
		t.Errorf("LoadLock of a missing lock gave %v, want core.ErrNotFound", err)
	}
}

func TestParseLockRejects(t *testing.T) {
	tests := []struct {
		name    string
		src     string
		message string
	}{
		{"empty", "", "empty"},
		{"a hand-added key", "version: 1\nnotes: mine\n", `unknown key "notes"`},
		{"another version", "version: 2\n", "lock version 2 is not supported"},
		{"no version", "flow_version: v0.3.0\n", "lock version 0 is not supported"},
		{"a timestamp that is not one", "version: 1\ncreated:\n  - {kind: k, id: i, at: soon}\n", `parsing time "soon"`},
		{"broken yaml", "version: 1\n\tbad\n", "tab character"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			lock, err := ParseLock([]byte(tt.src), "flow.lock")
			if err == nil {
				t.Fatalf("ParseLock succeeded with %#v", lock)
			}
			if !strings.Contains(err.Error(), tt.message) {
				t.Errorf("error %q does not mention %q", err, tt.message)
			}
			if core.ExitCode(err) != core.ExitUsage {
				t.Errorf("ExitCode = %d, want %d", core.ExitCode(err), core.ExitUsage)
			}
		})
	}
}

func TestParseLockDefaultsThePath(t *testing.T) {
	_, err := ParseLock([]byte("nope: true\n"), "")
	var parseErr *ParseError
	if !errors.As(err, &parseErr) {
		t.Fatalf("error is %T, want *ParseError", err)
	}
	if parseErr.Path != LockPath {
		t.Errorf("Path = %q, want %q", parseErr.Path, LockPath)
	}
}

func TestHash(t *testing.T) {
	got := Hash([]byte("hello"))
	const want = "sha256:2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824"
	if got != want {
		t.Errorf("Hash = %q, want %q", got, want)
	}
	if Hash([]byte("hello ")) == got {
		t.Error("Hash ignored a change in its input")
	}
}

// TestExampleLockParses keeps the shipped example honest: an example that the
// reader cannot load is worse than no example.
func TestExampleLockParses(t *testing.T) {
	path := filepath.Join("..", "..", "assets", "examples", "flow.lock")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	lock, err := ParseLock(data, path)
	if err != nil {
		t.Fatalf("ParseLock: %v", err)
	}
	rendered, err := lock.Bytes()
	if err != nil {
		t.Fatal(err)
	}
	if string(rendered) != string(data) {
		t.Errorf("the example is not what flow would write:\n%s\nwant\n%s", rendered, data)
	}
}
